import Foundation
import XCTest
@testable import TokenPulse

final class AlibabaTokenPlanProviderTests: XCTestCase {
    private let date = Date(timeIntervalSince1970: 1_790_985_600)
    private let quota = #"{"data":{"DataV2":{"data":{"data":{"per5HourPercentage":0.25,"per5HourResetTime":1791082800000,"per1WeekPercentage":0.8,"per1WeekResetTime":1791676800000,"perMonthPercentage":0.9}}}}}"#

    func testACS3MatchesPinnedOfficialNodeSignerWithFixedDateAndNonce() throws {
        // Generated by the exact official acs.ts at 8bbbbc7, replacing only
        // Date()/randomUUID() with these fixtures; see dedicated provider docs.
        for (region, golden) in [(ProviderRegion.china, "6fe665d5c65913a385e8e0268919d9449e0f8014aa199bc1e84eefb56085280e"), (.international, "877184d11610a528eaf6a9a5f7f72edf2c9d6901afe5871c01dcd2f5477fc374")] {
            let scope = try AlibabaTokenPlanCredential(key: "LTAIFixture:fixture-secret", region: region, site: .domestic)
            let request = AlibabaTokenPlanSigner.request(credential: scope, date: date, nonce: "00000000-0000-4000-8000-000000000001")
            XCTAssertEqual(request.url?.absoluteString, "https://\(scope.tokenHost)/modelstudio/cli/generateAccessToken")
            XCTAssertEqual(request.httpMethod, "POST")
            XCTAssertNil(request.httpBody)
            XCTAssertEqual(request.value(forHTTPHeaderField: "X-Acs-Date"), "2026-10-03T00:00:00Z")
            XCTAssertEqual(request.value(forHTTPHeaderField: "X-Acs-Content-Sha256"), "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855")
            XCTAssertEqual(request.value(forHTTPHeaderField: "Authorization"), "ACS3-HMAC-SHA256 Credential=LTAIFixture,SignedHeaders=content-type;host;x-acs-action;x-acs-content-sha256;x-acs-date;x-acs-signature-nonce;x-acs-version,Signature=\(golden)")
        }
    }

    func testExplicitFourTargetsAndFormContract() async throws {
        let expected: [(ProviderRegion, AlibabaTokenPlanSite, String, String)] = [
            (.china, .domestic, "bailian-cs.console.aliyun.com", "BroadScopeAspnGateway"),
            (.china, .international, "bailian-cs.console.alibabacloud.com", "BroadScopeAspnGateway"),
            (.international, .domestic, "modelstudio-cs.console.aliyun.com", "IntlBroadScopeAspnGateway"),
            (.international, .international, "bailian-singapore-cs.alibabacloud.com", "IntlBroadScopeAspnGateway")
        ]
        for (region, site, host, action) in expected {
            let scope = try AlibabaTokenPlanCredential(key: "LTAIFixture:fixture-secret", region: region, site: site)
            let transport = AlibabaTokenPlanTransport([#"{"cliAccessToken":"fixture-console-token"}"#, quota])
            let id = UUID()
            let result = try await ProviderQuotaClient(provider: .alibabaTokenPlan, transport: transport, now: { Date(timeIntervalSince1970: 1_790_985_600) }).quotaResult(for: id, credential: scope.envelope().encoded())
            XCTAssertEqual(result.snapshot.accountID, id)
            XCTAssertEqual(result.snapshot.sourceCredentialFingerprint, scope.fingerprint)
            XCTAssertNil(result.updatedCredential, "Console token is ephemeral, never synced or persisted")
            XCTAssertEqual(result.snapshot.windows.count, 2)
            XCTAssertEqual(result.snapshot.windows[0].usedPercentage, 25)
            XCTAssertEqual(result.snapshot.windows[0].resetsAt, Date(timeIntervalSince1970: 1_791_082_800))
            XCTAssertNil(result.snapshot.windows[0].isExhausted)
            XCTAssertNil(result.snapshot.windows[0].totalCount)
            let requests = await transport.requests
            XCTAssertEqual(requests.count, 2)
            XCTAssertEqual(requests[0].url?.host, scope.tokenHost)
            let request = requests[1]
            XCTAssertEqual(request.url?.host, host)
            let query = URLComponents(url: try XCTUnwrap(request.url), resolvingAgainstBaseURL: false)?.queryItems
            XCTAssertEqual(query?.first { $0.name == "action" }?.value, action)
            XCTAssertEqual(query?.first { $0.name == "api" }?.value, AlibabaTokenPlanProviderClient.usageAPI)
            XCTAssertEqual(request.value(forHTTPHeaderField: "Authorization"), "Bearer fixture-console-token")
            XCTAssertNil(request.value(forHTTPHeaderField: "X-Acs-Action"))
            let body = String(decoding: try XCTUnwrap(request.httpBody), as: UTF8.self)
            let pairs = body.split(separator: "&").map { $0.split(separator: "=", maxSplits: 1) }
            let form = Dictionary(uniqueKeysWithValues: pairs.map { (String($0[0]), String($0[1]).replacingOccurrences(of: "+", with: " ").removingPercentEncoding!) })
            XCTAssertEqual(form["region"], region.alibabaRegionID)
            let params = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(try XCTUnwrap(form["params"]).utf8)) as? [String: Any])
            XCTAssertEqual(params["Api"] as? String, AlibabaTokenPlanProviderClient.usageAPI)
            XCTAssertEqual(params["V"] as? String, "1.0")
            let business = try XCTUnwrap(params["Data"] as? [String: Any])
            XCTAssertEqual(Set(business.keys), ["cornerstoneParam"])
            let cornerstone = try XCTUnwrap(business["cornerstoneParam"] as? [String: Any])
            XCTAssertEqual(cornerstone["consoleSite"] as? String, "BAILIAN_ALIYUN")
            XCTAssertEqual(cornerstone["switchUserType"] as? Int, 3)
            XCTAssertNil(cornerstone["switchAgent"])
        }
    }

    func testActualKeysRegionAndSiteDefineCacheScopeAndRejectInferenceKey() throws {
        let auth = ProviderAuthenticationController()
        let encoded = try auth.credential(provider: .alibabaTokenPlan, apiKey: "LTAIFixture:secret:with:colons", region: .china, tokenPlanSite: .domestic)
        var envelope = try ProviderCredentialEnvelope.decode(encoded, expectedProvider: .alibabaTokenPlan)
        let identity = try XCTUnwrap(envelope.sourceCredentialIdentity)
        envelope.metadata["sourceCredentialFingerprint"] = "claimed-old-identity"
        XCTAssertEqual(envelope.sourceCredentialIdentity, identity)
        envelope.accessToken = "LTAIFixture:different-secret"
        XCTAssertNotEqual(envelope.sourceCredentialIdentity, identity)
        envelope.metadata["region"] = "international"
        let regional = envelope.sourceCredentialIdentity
        envelope.metadata["consoleSite"] = "international"
        XCTAssertNotEqual(envelope.sourceCredentialIdentity, regional)
        envelope.metadata["consoleSite"] = "evil.invalid"
        XCTAssertNil(envelope.sourceCredentialIdentity)
        for key in ["sk-sp-inference", "sk-sp-inference:secret", "id", "id:", "id:secret\n", "id:secret\r\nHost:evil", "id:two words"] {
            XCTAssertThrowsError(try auth.credential(provider: .alibabaTokenPlan, apiKey: key, region: .china, tokenPlanSite: .domestic))
        }
        XCTAssertThrowsError(try auth.credential(provider: .alibabaTokenPlan, apiKey: "id:secret", tokenPlanSite: .domestic))
        XCTAssertThrowsError(try auth.credential(provider: .alibabaTokenPlan, apiKey: "id:secret", region: .china))
    }

    func testNotLoginedRenewsExactlyOnceButPermissionDoesNotRetry() async throws {
        let scope = try AlibabaTokenPlanCredential(key: "fixture:secret", region: .china, site: .domestic)
        let expired = #"{"data":{"success":false,"errorCode":"NotLogined"}}"#
        let transport = AlibabaTokenPlanTransport([#"{"cliAccessToken":"first"}"#, expired, #"{"cliAccessToken":"second"}"#, quota])
        _ = try await AlibabaTokenPlanProviderClient(transport: transport, now: { Date() }).quota(accountID: UUID(), credential: scope.envelope())
        let requests = await transport.requests
        XCTAssertEqual(requests.count, 4)
        XCTAssertEqual(requests[1].value(forHTTPHeaderField: "Authorization"), "Bearer first")
        XCTAssertEqual(requests[3].value(forHTTPHeaderField: "Authorization"), "Bearer second")
        XCTAssertNotEqual(requests[0].value(forHTTPHeaderField: "X-Acs-Signature-Nonce"), requests[2].value(forHTTPHeaderField: "X-Acs-Signature-Nonce"))
        for (reply, expected) in [(expired, RefreshFailure.invalidCredential), (#"{"data":{"success":false,"errorCode":"AccessDenied"}}"#, .invalidCredential), (#"{"data":{"success":false}}"#, .server)] {
            let transport = AlibabaTokenPlanTransport([#"{"cliAccessToken":"first"}"#, reply, #"{"cliAccessToken":"second"}"#, reply])
            do {
                _ = try await AlibabaTokenPlanProviderClient(transport: transport, now: { Date() }).quota(accountID: UUID(), credential: scope.envelope())
                XCTFail("Expected failure")
            } catch { XCTAssertEqual(error as? RefreshFailure, expected) }
            let count = await transport.requests.count
            XCTAssertEqual(count, reply == expired ? 4 : 2)
        }
    }

    func testMissingValuesNeverBecomeZeroUnlimitedOrMonthlyQuota() throws {
        let id = UUID()
        let missing = try AlibabaTokenPlanProviderClient.snapshot(Data(#"{"data":{"per5HourResetTime":1791082800000}}"#.utf8), accountID: id, collectedAt: date)
        XCTAssertNil(missing.windows[0].usedPercentage)
        let empty = try AlibabaTokenPlanProviderClient.snapshot(Data(#"{"data":{}}"#.utf8), accountID: id, collectedAt: date)
        XCTAssertTrue(empty.windows.isEmpty)
        XCTAssertNotNil(empty.quotaStatusText)
        for text in [#"{"per5HourPercentage":15}"#, #"{"per5HourPercentage":-0.1}"#, #"{"per5HourPercentage":true}"#, #"{"per5HourPercentage":"0.2"}"#, #"{"per1WeekResetTime":-1}"#, #"{"unexpected":"shape"}"#, #"{"success":false,"per5HourPercentage":0}"#] {
            XCTAssertThrowsError(try AlibabaTokenPlanProviderClient.snapshot(Data(text.utf8), accountID: id, collectedAt: date))
        }
        let zero = try AlibabaTokenPlanProviderClient.snapshot(Data(#"{"data":"{\"per5HourPercentage\":0}"}"#.utf8), accountID: id, collectedAt: date)
        XCTAssertEqual(zero.windows.first?.usedPercentage, 0)
    }

    func testHTTPFailuresAndChangedResponseHostDoNotExposeQuota() async throws {
        let scope = try AlibabaTokenPlanCredential(key: "fixture:secret", region: .international, site: .international)
        for (status, failure) in [(401, RefreshFailure.invalidCredential), (403, .invalidCredential), (429, .rateLimited), (500, .server)] {
            let transport = AlibabaTokenPlanTransport([#"{"cliAccessToken":"fixture"}"#], status: status)
            do { _ = try await AlibabaTokenPlanProviderClient(transport: transport, now: { Date() }).quota(accountID: UUID(), credential: scope.envelope()); XCTFail("Expected failure") }
            catch { XCTAssertEqual(error as? RefreshFailure, failure) }
        }
        let foreign = AlibabaTokenPlanTransport([#"{"cliAccessToken":"fixture"}"#], responseURL: URL(string: "https://evil.invalid/token")!)
        do { _ = try await AlibabaTokenPlanProviderClient(transport: foreign, now: { Date() }).quota(accountID: UUID(), credential: scope.envelope()); XCTFail("Expected failure") }
        catch { XCTAssertEqual(error as? RefreshFailure, .server) }
    }

    @MainActor
    func testSiteRebindingClearsCacheOnFailureAndSynchronizesConfiguration() async throws {
        let suite = "TokenPulse.alibabaTokenPlan.fixture.\(UUID())"
        defer { UserDefaults(suiteName: suite)?.removePersistentDomain(forName: suite) }
        let accounts = LocalAccountStateStore(suiteName: suite)
        let configurations = LocalAccountConfigurationStore(suiteName: suite)
        let credentials = AlibabaTokenPlanMemoryCredentials()
        let query = AlibabaTokenPlanLocalQuery()
        let monitor = QuotaMonitor(accountStore: accounts, credentialStore: credentials, quotaClient: query, configurationStore: configurations)
        await monitor.start(refresh: false)
        let first = try AlibabaTokenPlanCredential(key: "fixture:secret", region: .china, site: .domestic)
        await monitor.addAccount(name: "Fixture", credential: try first.envelope().encoded(), provider: .alibabaTokenPlan)
        let id = try XCTUnwrap(monitor.states.first?.id)
        XCTAssertNotNil(monitor.states[0].snapshot)
        XCTAssertEqual(monitor.configuration(for: id)?.tokenPlanSite, .domestic)
        let second = try AlibabaTokenPlanCredential(key: "fixture:secret", region: .international, site: .international)
        await monitor.replaceCredential(try second.envelope().encoded(), accountID: id)
        XCTAssertNil(monitor.states[0].snapshot)
        XCTAssertEqual(monitor.states[0].lastFailure, .network)
        XCTAssertEqual(monitor.configuration(for: id)?.credentialIdentity, second.fingerprint)
        XCTAssertEqual(monitor.configuration(for: id)?.providerRegion, .international)
        XCTAssertEqual(monitor.configuration(for: id)?.tokenPlanSite, .international)
        let restored = QuotaMonitor(accountStore: accounts, credentialStore: credentials, quotaClient: query, configurationStore: configurations)
        await restored.start(refresh: false)
        XCTAssertNil(restored.states[0].snapshot)
        XCTAssertEqual(restored.configuration(for: id)?.tokenPlanSite, .international)
    }

    func testTwoPersonalWindowsHaveIndependentReminderScopes() throws {
        let id = UUID()
        let snapshot = try AlibabaTokenPlanProviderClient.snapshot(Data(#"{"per5HourPercentage":0.95,"per1WeekPercentage":0.96}"#.utf8), accountID: id, collectedAt: date)
        let plan = NotificationPlanner().planSuccessfulRefresh(accountID: id, accountName: "Fixture", previousSnapshot: nil, newSnapshot: snapshot, settings: AccountReminderSettings(), ledger: ReminderLedger(), now: date)
        let alerts = plan.operations.compactMap { if case .deliver(let value) = $0 { return value }; return nil }
        XCTAssertEqual(alerts.first?.kind, .quotaAlert)
        XCTAssertTrue(alerts.first?.body.contains("5 小时额度") == true)
        XCTAssertTrue(alerts.first?.body.contains("每周额度") == true)
        for window in snapshot.windows { XCTAssertNotNil(plan.ledger.cycleState(accountID: id, windowID: window.id)) }
    }

    func testRegistrationIconDemoWidgetAndLegacyConfiguration() throws {
        XCTAssertEqual(ProviderAuthenticationController().loginConfiguration(for: .alibabaTokenPlan).method, .apiKey)
        XCTAssertEqual(Provider.alibabaTokenPlan.iconAssetName, Provider.alibabaCodingPlan.iconAssetName)
        let account = try XCTUnwrap(DemoMode.accounts().first { $0.provider == .alibabaTokenPlan })
        let snapshot = DemoMode.snapshot(accountID: account.id, provider: account.provider, now: date)
        XCTAssertEqual(Set(snapshot.windows.compactMap(\.period)), [.fiveHour, .weekly])
        XCTAssertEqual(WidgetAccountSnapshot(account: account, windows: snapshot.windows, collectedAt: snapshot.collectedAt, lastFailure: nil).windows.count, 2)
        var configuration = AccountConfiguration(account: account)
        configuration.providerRegion = .international
        configuration.tokenPlanSite = .domestic
        XCTAssertEqual(try JSONDecoder().decode(AccountConfiguration.self, from: JSONEncoder().encode(configuration)), configuration)
        var old = try XCTUnwrap(JSONSerialization.jsonObject(with: JSONEncoder().encode(configuration)) as? [String: Any])
        old["tokenPlanSite"] = nil
        XCTAssertNil(try JSONDecoder().decode(AccountConfiguration.self, from: JSONSerialization.data(withJSONObject: old)).tokenPlanSite)
    }
}

private actor AlibabaTokenPlanTransport: ProviderTransport {
    var requests: [URLRequest] = []
    private var replies: [String]
    private let status: Int
    private let responseURL: URL?
    init(_ replies: [String], status: Int = 200, responseURL: URL? = nil) {
        self.replies = replies; self.status = status; self.responseURL = responseURL
    }
    func data(for request: URLRequest) async throws -> (Data, URLResponse) {
        requests.append(request)
        guard !replies.isEmpty else { throw URLError(.badServerResponse) }
        return (Data(replies.removeFirst().utf8), HTTPURLResponse(url: responseURL ?? request.url!, statusCode: status, httpVersion: nil, headerFields: nil)!)
    }
}

private actor AlibabaTokenPlanMemoryCredentials: CredentialStoring {
    var values: [UUID: String] = [:]
    func save(_ value: String, for id: UUID) { values[id] = value }
    func credential(for id: UUID) -> String? { values[id] }
    func deleteCredential(for id: UUID) { values[id] = nil }
}
private actor AlibabaTokenPlanLocalQuery: QuotaQuerying {
    var calls = 0
    func quota(for id: UUID, credential: String) async throws -> QuotaSnapshot {
        calls += 1
        if calls > 1 { throw RefreshFailure.network }
        return try AlibabaTokenPlanProviderClient.snapshot(Data(#"{"per5HourPercentage":0.25}"#.utf8), accountID: id, collectedAt: Date())
    }
}
